"use strict";

// The package's whole callable API is chosen AT RUNTIME. Which of the two
// functions below becomes `module.exports` depends on an environment flag
// this analyzer models nothing about -- so neither one is the module's
// exported value, and no static answer about "the" exported function is
// available (RWF-014).
const danger = require("./danger");

// The branch that reaches the vulnerable sink. Nothing in this file calls
// it: the ONLY way it ever runs is by being the module's exported value.
function dangerousOp(input) {
  return danger.explode(input);
}

// The branch that does not. Structurally interchangeable with the one
// above at the assignment site -- both are bare identifiers naming a
// same-file function declaration, so `unwrapValue` is irrelevant here and
// RWF-012's chained-assignment guard never engages (RWF-014 is the
// plain-identifier form of the same defect).
function safeOp(input) {
  return "safe:" + input;
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
} else {
  module.exports = safeOp;
}
